"use strict";(()=>{document.documentElement.dataset.backrowExtension=chrome.runtime.getManifest().version;document.dispatchEvent(new CustomEvent("backrow:extension-ready"));chrome.storage.local.get("remoteLog").then(({remoteLog:e})=>{e===!0&&(document.documentElement.dataset.backrowRemoteLog="1",document.dispatchEvent(new CustomEvent("backrow:remote-log")))});document.addEventListener("backrow:join",e=>{let t=e.detail;if(typeof t=="string")try{let{roomId:n,keyText:o,url:r}=JSON.parse(t);if(typeof n!="string"||typeof o!="string"||typeof r!="string")return;let s={type:"join",roomId:n,keyText:o,url:r};chrome.runtime.sendMessage(s)}catch{}});})();
